cd /work/workspace && python3 << 'EOF'
import json, csv, collections

bal = collections.defaultdict(lambda: [0.0, 0.0])
# opening
for r in csv.DictReader(open('documents/opening_trial_balance.csv')):
    d, c = float(r['debit']), float(r['credit'])
    bal[r['account']][0] += d; bal[r['account']][1] += c
# JEs
for je in json.load(open('deliverable/month_01/journal_entries.json')):
    s = [0,0]
    for l in je['lines']:
        bal[l['account']][0] += l['debit']; bal[l['account']][1] += l['credit']
        s[0]+=l['debit']; s[1]+=l['credit']
    assert round(s[0],2)==round(s[1],2), je['ref']

names = {'1000':'Cash — Operating','1100':'Accounts receivable','1300':'Prepaid expenses','1500':'Computer equipment','1510':'Accumulated depreciation','2000':'Accounts payable','2200':'Deferred revenue — current','3000':'Common stock & APIC','3900':'Retained earnings','4000':'Subscription revenue','5000':'Hosting & infrastructure','5100':'Rent','5200':'Software & tools','5300':'Marketing','5400':'G&A — other','6000':'Salaries & wages','6100':'Payroll taxes & benefits','6200':'Depreciation'}
out = {"as_of":"2025-01-31","accounts":{}}
td=tc=0
for a in sorted(bal):
    d,c = bal[a]
    net = round(d-c,2)
    if net >= 0: dd,cc = net, 0.0
    else: dd,cc = 0.0, -net
    out["accounts"][a] = {"name": names.get(a,a), "debit": dd, "credit": cc}
    td+=dd; tc+=cc
out["totals"] = {"debit": round(td,2), "credit": round(tc,2)}
json.dump(out, open('deliverable/month_01/trial_balance.json','w'), indent=2)
print("TB debits", round(td,2), "credits", round(tc,2))
for a in sorted(bal): print(a, bal[a])
EOF

